          "beat": "转折",
          "sourceBlockIds": ["B35"]
        }
      ]
    },
    {
      "duration": 5,
      "cast": ["皇家大魔导师", "亚瑟", "黑龙"],
      "props": ["苹果"],
      "startPosition": "亚瑟背对黑龙站在雪地上，右手拿着苹果，面朝皇家大魔导师；黑龙停在亚瑟身后，低头张口；皇家大魔导师站在亚瑟前方。",
      "clips": [
        {
          "duration": 2,
          "size": "CU",
          "cameraMove": "轻微推近",
