        {
          "duration": 3,
          "size": "MCU",
          "cameraMove": "跟拍转身",
          "visualAction": "亚瑟微微一笑，转过身面对黑龙，随后右手举起苹果，将苹果展示在黑龙前方。",
          "beat": "反击铺垫",
          "sourceBlockIds": ["B37", "B38"]
        }
      ]
    },
    {
      "duration": 8,
      "cast": ["亚瑟", "黑龙", "皇家大魔导师", "男弟子", "女弟子"],
      "props": ["苹果"],
