      "clips": [
        {
          "duration": 2,
          "size": "MS",
          "cameraMove": "固定机位",
          "visualAction": "黑龙朝亚瑟喷出火焰，亚瑟站在原地，眼睛看着火焰。",
          "beat": "危机",
          "sourceBlockIds": ["B39"]
        },
        {
          "duration": 4,
          "size": "MS",
          "cameraMove": "快速跟拍",
          "visualAction": "亚瑟右手用力将苹果掷出，苹果飞出击中黑龙眼睛，黑龙扭头咆哮并被击退飞走。",
