          "sourceBlockIds": ["B40", "B41"]
        },
        {
          "duration": 2,
          "size": "MCU",
          "cameraMove": "固定机位",
          "visualAction": "皇家大魔导师与男弟子、女弟子站在原地，瞪大眼睛，张口不动。",
          "beat": "反应",
          "sourceBlockIds": ["B42"]
        }
      ]
    }
  ]
